{{#each Echo }}
```kql
let _nodeId = "{{this._nodeId}}";
let _timeOfFault = todatetime("{{this._timeOfFault}}");
let data = cluster('wdgeventstore').database('hostosdeploy').nodes
| where nodeId == _nodeId
| project nodeId, machineName, tenant;
let socMachineName = data | project strcat(machineName, "SOC");
cluster('azcore.centralus').database('OvlProd').LinuxOverlakeSystemd
| where PreciseTimeStamp > _timeOfFault - 1h and PreciseTimeStamp < _timeOfFault + 1h
| where MachineName in (socMachineName)
| where SYSLOG_IDENTIFIER in ("NodeService")
| project PreciseTimeStamp, SYSLOG_IDENTIFIER, PORTABLE_EXTENSION_NAME_AND_VERSION, _PID, MESSAGE
```
